<div class="quote-inbox"><section class="admin-page-head"><div><p class="admin-kicker">Comercial</p><h1>Cotizaciones</h1><p>Recibe, verifica y prepara las cotizaciones de todos tus canales. Cada registro conserva su origen y el seguimiento con el cliente.</p></div><?php if($canCapture):?><a class="admin-primary-button" data-admin-form-link href="/admin/quotes/intake">Nueva cotización</a><?php endif?></section>
<div class="quote-flow-guide"><div><span>1</span><strong>Recibe</strong><p>Desde el sitio o capturada por tu equipo.</p></div><div><span>2</span><strong>Verifica</strong><p>Revisa existencias y acuerda los faltantes.</p></div><div><span>3</span><strong>Prepara</strong><p>Confirma productos, precios y total.</p></div><div><span>4</span><strong>Comparte</strong><p>Entrega el resultado y registra a quién lo enviaste.</p></div></div>
<form class="admin-panel quote-inbox-filters" method="get" action="/admin/quotes" aria-label="Filtros de cotizaciones"><label class="admin-field"><span>Buscar folio o cliente</span><input name="q" maxlength="120" type="search" value="<?= e($filters['q']) ?>" placeholder="Nombre o referencia"></label><?php foreach(['origin'=>['Origen',Flow::ORIGINS],'stage'=>['Seguimiento',Flow::STAGES]] as $key=>[$label,$options]):?><label class="admin-field"><span><?= e($label) ?></span><select name="<?= e($key) ?>"><option value="">Todos</option><?php foreach($options as $value=>$text):?><option value="<?= e($value) ?>" <?= $filters[$key]===$value?'selected':'' ?>><?= e($text) ?></option><?php endforeach?></select></label><?php endforeach?><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= (string)$filters['branch_id']===(string)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Responsable</span><select name="assigned_user_id"><option value="">Todos</option><option value="<?= e($user->id) ?>" <?= (string)$filters['assigned_user_id']===(string)$user->id?'selected':'' ?>>Mis cotizaciones</option><?php foreach($assignees??[] as $assignee):if((int)$assignee['id']===$user->id)continue;?><option value="<?= e($assignee['id']) ?>" <?= (string)$filters['assigned_user_id']===(string)$assignee['id']?'selected':'' ?>><?= e($assignee['display_name']) ?></option><?php endforeach?></select></label><details class="quote-filter-more"><summary>Estado del documento</summary><label class="admin-field"><span>Estado comercial</span><select name="status"><option value="">Todos</option><?php foreach(QuoteRules::LABELS as $key=>$label):?><option value="<?= e($key) ?>" <?= $filters['status']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach?></select></label></details><div class="quote-filter-actions"><button class="admin-primary-button" type="submit">Buscar</button><a class="admin-secondary-button" href="/admin/quotes">Limpiar</a></div></form>
<section class="admin-panel quote-inbox-list"><header><div><h2>Bandeja de cotizaciones</h2><p>Abre un registro para revisar lo solicitado y continuar su atención.</p></div><span class="cms-list-count"><?= e(count($page->items)) ?> en esta página</span></header><?php if(!$page->items):?><div class="quote-inbox-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/></svg><h3><?= $filtered?'No hay cotizaciones con esos filtros':'Todo comienza con lo que necesita tu cliente' ?></h3><p><?= $filtered?'Prueba otro origen, seguimiento o sucursal para encontrar el registro.':'Las solicitudes del sitio aparecen aquí. Si llegan por correo, WhatsApp, teléfono o en sucursal, regístralas para darles el mismo seguimiento.' ?></p><?php if($filtered):?><a class="admin-secondary-button" href="/admin/quotes">Ver todas</a><?php elseif($canCapture):?><a class="admin-primary-button" data-admin-form-link href="/admin/quotes/intake">Registrar cotización</a><?php endif?></div><?php else:?><div class="quote-inbox-rows"><?php foreach($page->items as $row):?><a class="quote-inbox-row" data-admin-form-link href="/admin/quotes/workflow?kind=<?= e($row['kind']) ?>&amp;id=<?= e($row['source_id']) ?>"><div><strong><?= e($row['full_name']) ?></strong><?php if(($row['requester_name']??'')!==''&&$row['requester_name']!==$row['full_name']):?><small>Solicitó: <?= e($row['requester_name']) ?></small><?php endif?><small><?= e($row['reference']) ?></small><?php if(($row['document_folio']??'')!==''&&$row['document_folio']!==$row['reference']):?><small>Documento: <?= e($row['document_folio']) ?></small><?php endif?></div><div><span class="quote-origin"><?= e(Flow::ORIGINS[$row['origin']]) ?></span><small><?= e($row['branch_name']) ?></small></div><div><span class="quote-stage" data-stage="<?= e($row['stage']) ?>"><?= e(Flow::STAGES[$row['stage']]) ?></span><?php if($row['document_status']):?><small>Documento: <?= e(QuoteRules::LABELS[$row['document_status']]??$row['document_status']) ?></small><?php endif?></div><div><span><?= e($row['assigned_name']??'Sin responsable') ?></span><small><?= $row['total']===null?'Total por preparar':'$'.e($row['total']).' MXN' ?></small></div><span class="quote-row-open">Abrir ↗</span></a><?php endforeach?></div><?php endif?>
<?php if($page->offset||$page->hasMore):?><nav class="cms-list-pagination" aria-label="Paginación"><?php $params=array_diff_key($filters,['offset'=>true]);if($page->offset):?><a class="admin-secondary-button" href="/admin/quotes?<?= e(http_build_query($params+['offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a class="admin-secondary-button" href="/admin/quotes?<?= e(http_build_query($params+['offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></section></div>
